class _JokesState extends State<_Jokes>{int i=0;bool show=false;static const jokes=< (String,String)>[
('المعلم: لماذا كتاب الرياضيات حزين؟','لأنه مليان مسائل وما لقى لها حل!'),('واحد اشترى ساعة ذكية','كلما سألها عن الوقت قالت: حدّثني أولاً!'),('طالب قال: ذاكرت من الفجر!','سألوه: أين وصلت؟ قال: وصلت لقرار أنام!'),('لماذا الكمبيوتر بارد؟','لأن عنده نوافذ مفتوحة!'),('هل عندكم كتاب عن الثقة بالنفس؟','نعم، خذه بنفسك من الرف!'),('الهاتف قال للشاحن','أنت تعطيني طاقة ولا تطلب كلمة مرور!'),('واحد نام مبكراً ليصحو نشيطاً','استيقظ وقرر تأجيل النشاط إلى الغد!'),('لماذا القلم لا يحب الزحام؟','لأنه يحب أن يكتب على راحته!'),('كيف ذاكرتك؟','ممتازة، بس نسيت أين وضعتها!'),('لماذا الكتاب متفائل؟','لأنه يعرف أن لكل صفحة بداية جديدة!'),('اشترى حذاء رياضياً','لبسه وجلس يشجعه حتى يمشي!'),('قال المنبه: قم!','رد: لا ترفع صوتك، أنا صاحي في أحلامي!')];
