class _Stories extends StatefulWidget{const _Stories();@override State<_Stories> createState()=>_StoriesState();}
class _StoriesState extends State<_Stories>{final Set<int> open={};static const stories=< (String,String,String)>[
('العصفور والبذرة','وجد عصفور بذرة صغيرة، فغرسها في تربة رطبة وظل يعتني بها. كبرت وصارت شجرة يستظل بها وأصدقاؤه.','العمل الصغير المستمر يصنع أثراً كبيراً.'),('مصباح القرية','وضع فتى مصباحاً أمام بيته في طريق مظلم. تبعه جاره ثم بقية أهل القرية، فأضاء الطريق كله.','المبادرة الطيبة تشجع الآخرين.'),('التاجر والميزان','لاحظ تاجر خللاً في ميزانه فأصلحه وأخبر زبائنه. كسب ثقتهم لأنهم وجدوا عنده الأمانة.','الصدق أساس الثقة.'),('النملة والمطر','وجدت نملة قطرة مطر تعترض طريقها، فبحثت عن مسار آمن ثم أرشدت صديقاتها إليه.','التفكير والتعاون يحلان المشكلات.'),('الكتاب القديم','وجدت طفلة كتاباً قديماً وبدأت تقرأه، فاكتشفت عالماً من الأفكار وصارت تخصص وقتاً للقراءة.','قيمة الشيء فيما يقدمه لا في مظهره.'),('الراعي والنجمة','تعلم راعٍ أسماء النجوم ودوّن مواقعها، حتى صار يرشد المسافرين في الليل.','الملاحظة والتدوين يثبتان المعرفة.'),('النهر والحجر','ظن حجر صغير أنه لا يؤثر في النهر، لكنه ساعد مع الزمن على تغيير مجرى الماء حوله.','لا تستهن بالأثر الصغير.'),('النافذة الخضراء','زرعت امرأة نبتة قرب نافذتها واعتنت بها كل يوم، حتى أصبحت زاوية البيت أجمل مكان فيه.','العناية اليومية تصنع الجمال.')];
 @override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(14),children:[const Text('قصص عربية قصيرة أصلية',style:TextStyle(color:gold,fontSize:21,fontWeight:FontWeight.w900)),...List.generate(stories.length,(i){final s=stories[i];final yes=open.contains(i);return Card(color:const Color(0xFF292641),child:Column(children:[ListTile(title:Text(s.$1),subtitle:Text(yes?'اضغط للإغلاق':'اضغط لقراءة القصة'),trailing:Icon(yes?Icons.expand_less:Icons.expand_more),onTap:()=>setState(()=>yes?open.remove(i):open.add(i))),if(yes)Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s.$2,style:const TextStyle(height:1.8)),const SizedBox(height:8),Text('العبرة: '+s.$3,style:const TextStyle(color:gold,fontWeight:FontWeight.bold))]))]));})]);}}
